import type { LessonContent } from './types';

function lg(day: number, topic: string, topicName: string, title: string, obj: string[], steps: string[], hint: string, hintCode: string, solDesc: string, solCode: string, success: string[], takeaway: string): LessonContent {
  return { topicSlug: topic, topicName, domainSlug: 'logistics', dayNumber: day, title, duration: 30, objectives: obj, steps: steps.map(s => ({ instruction: s })), hint: { description: hint, code: hintCode }, fullSolution: { description: solDesc, code: solCode }, successCriteria: success, keyTakeaway: takeaway };
}

export const logisticsLessons: LessonContent[] = [
  lg(1,'supply-chain','Supply Chain Fundamentals','Supply Chain Mapping',['Map a supply chain network with nodes and flows','Calculate end-to-end lead times'],['List all nodes: suppliers, factories, warehouses, DCs, retailers','Identify material flows between nodes','Assign lead times (days) to each link','Calculate critical path (longest total lead time)','Identify bottleneck node','Visualize as directed graph'],'Use networkx to model the chain as a directed graph. The critical path is the longest path from raw material to customer.','import networkx as nx\n\nG = nx.DiGraph()\nG.add_edge("Supplier","Factory",lead=5)\nG.add_edge("Factory","Warehouse",lead=3)\nG.add_edge("Warehouse","DC",lead=2)\nG.add_edge("DC","Retailer",lead=1)\ntotal = nx.dag_longest_path_length(G, weight="lead")\nprint("Lead time: {} days".format(total))\nprint("Path: {}".format(" > ".join(nx.dag_longest_path(G, weight="lead"))))','Complete supply chain network model.','import networkx as nx\n\nG = nx.DiGraph()\nnodes = {"Supplier_A":"China","Supplier_B":"Vietnam","Factory":"assembly",\n    "Central_WH":"storage","DC_East":"distribution","DC_West":"distribution",\n    "Retail_NYC":"retail","Retail_LA":"retail"}\nfor n, t in nodes.items(): G.add_node(n, type=t)\n\nedges = [("Supplier_A","Factory",14,2.50),("Supplier_B","Factory",10,3.00),\n    ("Factory","Central_WH",3,1.00),("Central_WH","DC_East",2,0.80),\n    ("Central_WH","DC_West",4,1.20),("DC_East","Retail_NYC",1,0.50),\n    ("DC_West","Retail_LA",1,0.50)]\nfor u,v,lead,cost in edges:\n    G.add_edge(u, v, lead_days=lead, cost_per_unit=cost)\n\nprint("=== Supply Chain Analysis ===")\nfor target in ["Retail_NYC","Retail_LA"]:\n    for path in nx.all_simple_paths(G, "Supplier_A", target):\n        lead = sum(G[u][v]["lead_days"] for u,v in zip(path, path[1:]))\n        cost = sum(G[u][v]["cost_per_unit"] for u,v in zip(path, path[1:]))\n        print("{}: {} days, {:.2f}/unit".format(" > ".join(path), lead, cost))\n\nbottleneck = max(G.nodes(), key=lambda n: G.degree(n))\nprint("Bottleneck: {} (degree {})".format(bottleneck, G.degree(bottleneck)))\nprint("Nodes: {}, Links: {}".format(G.number_of_nodes(), G.number_of_edges()))',['6+ nodes across tiers','Lead time for 2+ paths','Bottleneck identified','Network visualized'],'A supply chain map reveals what spreadsheets hide.'),
  lg(2,'supply-chain','Supply Chain Fundamentals','Supplier Evaluation Matrix',['Build weighted scoring matrix','Apply total cost of ownership'],['Define 5 criteria: quality, cost, delivery, flexibility, stability','Assign weights summing to 100%','Score each supplier 1-10','Calculate weighted scores and rank','Add TCO: unit price + shipping + quality cost + holding','Visualize as radar chart'],'Weight by business priority. If delivery is critical, give it 30%. Weights reflect strategy.','import pandas as pd\ncriteria = {"Quality":0.25,"Cost":0.30,"Delivery":0.25,"Flex":0.10,"Stability":0.10}\nsuppliers = {"Acme":{"Quality":8,"Cost":7,"Delivery":9,"Flex":6,"Stability":8},\n    "Beta":{"Quality":7,"Cost":9,"Delivery":6,"Flex":8,"Stability":7}}\nfor name, scores in suppliers.items():\n    total = sum(scores[c]*criteria[c] for c in criteria)\n    print("{}: {:.2f}/10".format(name, total))','Complete supplier scorecard with radar chart.','import pandas as pd\nimport numpy as np\n\ncriteria = {"Quality":0.25,"Unit Cost":0.20,"On-Time":0.25,"Flexibility":0.15,"Stability":0.15}\nsuppliers = {"Acme":[8,7,9,6,8],"Beta":[7,9,6,8,7],"Gamma":[9,6,8,7,9]}\ndf = pd.DataFrame(suppliers, index=criteria.keys())\ndf["Weight"] = criteria.values()\n\nprint("=== Supplier Scores ===")\nfor s in suppliers:\n    score = sum(df[s]*df["Weight"])\n    print("  {}: {:.2f}/10".format(s, score))\n\ntco = {"Acme":{"unit":12.00,"ship":1.50,"quality":0.20,"hold":0.80},\n    "Beta":{"unit":10.50,"ship":2.00,"quality":0.50,"hold":1.20},\n    "Gamma":{"unit":13.00,"ship":1.00,"quality":0.10,"hold":0.60}}\nprint("\\n=== Total Cost of Ownership ===")\nfor name, costs in tco.items():\n    total = sum(costs.values())\n    hidden = total - costs["unit"]\n    print("  {}: {:.2f}/unit (unit: {:.2f}, hidden: {:.2f})".format(name, total, costs["unit"], hidden))',['5+ weighted criteria','3+ suppliers ranked','TCO includes hidden costs','Radar chart comparison'],'The cheapest supplier is rarely lowest-cost — TCO reveals hidden costs.'),
  lg(3,'supply-chain','Supply Chain Fundamentals','Economic Order Quantity',['Calculate EOQ and cost trade-offs','Run sensitivity analysis'],['Identify inputs: annual demand D, ordering cost S, holding cost H','Apply: EOQ = sqrt(2*D*S/H)','Calculate total annual cost','Plot total cost curve','Sensitivity: what if demand doubles?','Calculate reorder point'],'EOQ = sqrt(2DS/H). Ordering cost decreases with larger orders while holding cost increases. EOQ is the balance.','import math\nD = 10000  # annual demand\nS = 50     # cost per order\nH = 2      # holding cost/unit/year\nEOQ = math.sqrt(2*D*S/H)\nprint("EOQ: {:.0f} units".format(EOQ))\nprint("Orders/year: {:.1f}".format(D/EOQ))\nprint("Total cost: {:.0f}".format((D/EOQ)*S + (EOQ/2)*H))','EOQ calculator with cost curve and sensitivity.','import numpy as np\nimport matplotlib.pyplot as plt\n\ndef eoq(D, S, H):\n    q = np.sqrt(2*D*S/H)\n    orders = D/q\n    total = (D/q)*S + (q/2)*H\n    return q, orders, total\n\nD, S, H = 10000, 50, 2\nq, o, t = eoq(D, S, H)\nprint("Base: EOQ={:.0f}, Orders={:.1f}, Cost={:.0f}".format(q, o, t))\n\nprint("\\n=== Sensitivity ===")\nfor label, d, s, h in [("Demand 2x",D*2,S,H),("Order cost 2x",D,S*2,H),("Holding 3x",D,S,H*3)]:\n    q2,o2,t2 = eoq(d, s, h)\n    print("  {}: EOQ={:.0f}, Cost={:.0f}".format(label, q2, t2))\n\nQ = np.arange(50, 2000, 10)\nordering = (D/Q)*S\nholding = (Q/2)*H\ntotal = ordering + holding\n\nfig, ax = plt.subplots(figsize=(10,6))\nax.plot(Q, ordering, "--", label="Ordering", color="#e63946")\nax.plot(Q, holding, "--", label="Holding", color="#2a9d8f")\nax.plot(Q, total, "-", label="Total", color="#a8dadc", linewidth=2)\nax.axvline(x=q, color="#e9c46a", linestyle=":", label="EOQ={:.0f}".format(q))\nax.set_xlabel("Order Qty"); ax.set_ylabel("Annual Cost")\nax.set_title("EOQ Cost Curve"); ax.legend()\nax.set_facecolor("#0b1d2a"); fig.set_facecolor("#091722")\nax.tick_params(colors="#a8dadc")\nplt.tight_layout()\nplt.savefig("eoq.png", dpi=150, facecolor="#091722")\n\nlead = 7; safety = 50\nrop = D/365 * lead + safety\nprint("\\nReorder Point: {:.0f} units".format(rop))',['EOQ formula correct','Cost curve shows trade-off','3+ sensitivity scenarios','Reorder point includes safety stock'],'EOQ balances ordering too often vs ordering too much.'),
  lg(4,'supply-chain','Supply Chain Fundamentals','Supply Chain Risk Management',['Build a risk matrix','Develop mitigation strategies'],['Brainstorm 8+ risks','Score probability (1-5) and impact (1-5)','Plot on risk matrix','Color: red >15, yellow 8-15, green <8','Define mitigation for red/yellow','Calculate annual risk exposure'],'Focus on top-right quadrant (high prob + high impact). Single-source suppliers are almost always highest risk.','risks = [\n    {"risk":"Single source","prob":4,"impact":5},\n    {"risk":"Port congestion","prob":3,"impact":4},\n    {"risk":"Quality defect","prob":3,"impact":3},\n]\nfor r in risks:\n    score = r["prob"]*r["impact"]\n    level = "RED" if score>15 else "YELLOW" if score>8 else "GREEN"\n    print("[{}] {}: {} ({}x{})".format(level, r["risk"], score, r["prob"], r["impact"]))','Complete risk matrix with mitigations.','import pandas as pd\n\nrisks = pd.DataFrame([\n    {"risk":"Single-source failure","prob":4,"impact":5,"cat":"Supply",\n     "mitigation":"Qualify second source; 30-day buffer stock"},\n    {"risk":"Port closure","prob":3,"impact":4,"cat":"Logistics",\n     "mitigation":"Diversify ports; air freight contingency"},\n    {"risk":"Quality defect batch","prob":3,"impact":4,"cat":"Quality",\n     "mitigation":"Incoming inspection; supplier audits"},\n    {"risk":"Demand spike >30%","prob":2,"impact":4,"cat":"Demand",\n     "mitigation":"Safety stock for A-items; flex agreements"},\n    {"risk":"Cyber attack on ERP","prob":2,"impact":5,"cat":"Tech",\n     "mitigation":"Offline backup; incident response plan"},\n    {"risk":"Tariff change","prob":3,"impact":3,"cat":"Compliance",\n     "mitigation":"Multi-country sourcing; FTZ utilization"},\n    {"risk":"Transport strike","prob":2,"impact":3,"cat":"Logistics",\n     "mitigation":"Multi-modal contracts; pre-positioning"},\n    {"risk":"Natural disaster","prob":1,"impact":5,"cat":"Environment",\n     "mitigation":"Geographic diversification; BCP"},\n])\n\nrisks["score"] = risks["prob"] * risks["impact"]\nrisks["level"] = risks["score"].apply(lambda s: "RED" if s>15 else ("YELLOW" if s>8 else "GREEN"))\n\nprint("=== Risk Matrix ===")\nfor _, r in risks.sort_values("score", ascending=False).iterrows():\n    icon = {"RED":"!!","YELLOW":"! ","GREEN":"ok"}[r["level"]]\n    print("[{}] {:2d} {}: {}".format(icon, r["score"], r["risk"], r["mitigation"]))\n\nprint("\\nRED: {}  YELLOW: {}  GREEN: {}".format(\n    (risks.level=="RED").sum(), (risks.level=="YELLOW").sum(), (risks.level=="GREEN").sum()))\n\nrisks["freq"] = [0.3,0.5,0.4,0.2,0.1,0.3,0.15,0.05]\nrisks["cost_if"] = [500000,200000,150000,300000,1000000,100000,80000,2000000]\nrisks["exposure"] = risks["freq"]*risks["cost_if"]\nprint("Annual exposure: {:,.0f}".format(risks["exposure"].sum()))',['8+ risks scored','Red/yellow/green applied','Each high-risk has mitigation','Dollar exposure calculated'],'Risk management: know which disruptions hurt most and have a plan.'),
  lg(5,'supply-chain','Supply Chain Fundamentals','Supply Chain KPIs (SCOR)',['Calculate SCOR metrics','Build SC performance dashboard'],['Define SCOR L1: reliability, responsiveness, agility, cost, assets','Calculate Perfect Order Rate = on-time x in-full x no-damage x correct-docs','Calculate Cash-to-Cash = DIO + DSO - DPO','Calculate Inventory Turns = COGS / Avg Inventory','Calculate Order Fulfillment Cycle Time','Create dashboard summary'],'Perfect Order Rate multiplies 4 components — 95% on each gives only 81% perfect.','on_time = 0.95; in_full = 0.97; no_damage = 0.99; correct = 0.98\npor = on_time * in_full * no_damage * correct\nprint("Perfect Order Rate: {:.1%}".format(por))\n\nDIO, DSO, DPO = 45, 35, 30\nprint("Cash-to-Cash: {} days".format(DIO + DSO - DPO))','Complete SCOR dashboard.','data = {"on_time":0.94,"in_full":0.96,"no_damage":0.99,"correct_docs":0.97,\n    "fulfillment_days":4.2,"flex_pct":20,"flex_days":30,\n    "sc_cost":12000000,"revenue":100000000,"cogs":65000000,\n    "avg_inv":8000000,"avg_recv":10000000,"avg_pay":7000000}\n\npor = data["on_time"]*data["in_full"]*data["no_damage"]*data["correct_docs"]\nturns = data["cogs"]/data["avg_inv"]\ndio = data["avg_inv"]/data["cogs"]*365\ndso = data["avg_recv"]/data["revenue"]*365\ndpo = data["avg_pay"]/data["cogs"]*365\nc2c = dio + dso - dpo\nsc_pct = data["sc_cost"]/data["revenue"]*100\n\nprint("=== SCOR Dashboard ===")\nkpis = [\n    ("Perfect Order Rate","{:.1%}".format(por),"90%+"),\n    ("Fulfillment Cycle","{:.1f} days".format(data["fulfillment_days"]),"<5 days"),\n    ("SC Cost % Revenue","{:.1f}%".format(sc_pct),"<12%"),\n    ("Inventory Turns","{:.1f}x".format(turns),">8x"),\n    ("Cash-to-Cash","{:.0f} days".format(c2c),"<40 days"),\n    ("DIO","{:.0f} days".format(dio),"-"),\n    ("DSO","{:.0f} days".format(dso),"-"),\n    ("DPO","{:.0f} days".format(dpo),"-"),\n]\nfor name, val, bench in kpis:\n    print("  {}: {} (benchmark: {})".format(name, val, bench))',['Perfect Order calculated','Cash-to-Cash computed','Inventory turns correct','Benchmarks compared'],'SCOR provides a common language for SC performance.'),
  lg(1,'inventory-mgmt','Inventory Management','ABC Analysis',['Classify inventory with Pareto 80/20','Assign policies by ABC class'],['Load: SKU, unit cost, annual demand','Calculate annual value = cost x demand','Sort descending by value','Compute cumulative %','Classify: A=80%, B=95%, C=100%','Create Pareto chart'],'A items (~20% SKUs, ~80% value) get tight control. C items (~50% SKUs, ~5% value) get simple rules.','import pandas as pd, numpy as np\nnp.random.seed(42)\ndf = pd.DataFrame({"sku":["SKU-{:03d}".format(i) for i in range(100)],\n    "cost":np.random.uniform(1,500,100),"demand":np.random.randint(10,5000,100)})\ndf["value"] = df["cost"]*df["demand"]\ndf = df.sort_values("value",ascending=False)\ndf["cum_pct"] = df["value"].cumsum()/df["value"].sum()*100\ndf["cls"] = df["cum_pct"].apply(lambda x: "A" if x<=80 else ("B" if x<=95 else "C"))\nprint(df.groupby("cls").agg(skus=("sku","count"),value=("value","sum")).to_string())','Complete ABC analyzer with Pareto chart.','import pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\n\nnp.random.seed(42)\nn = 200\ndf = pd.DataFrame({"sku":["SKU-{:04d}".format(i) for i in range(n)],\n    "cost":np.random.lognormal(3,1.5,n).round(2),\n    "demand":np.random.lognormal(5,1.2,n).astype(int)+1,\n    "cat":np.random.choice(["Elec","Mech","Consumable","Pkg"],n)})\ndf["value"] = (df["cost"]*df["demand"]).round(2)\ndf = df.sort_values("value",ascending=False).reset_index(drop=True)\ndf["cum_pct"] = df["value"].cumsum()/df["value"].sum()*100\ndf["abc"] = df["cum_pct"].apply(lambda x: "A" if x<=80 else ("B" if x<=95 else "C"))\n\nprint("=== ABC Summary ===")\nfor cls in ["A","B","C"]:\n    sub = df[df.abc==cls]\n    print("  {}: {} SKUs ({:.0f}%), value {:,.0f} ({:.0f}%)".format(\n        cls, len(sub), len(sub)/n*100, sub["value"].sum(), sub["value"].sum()/df["value"].sum()*100))\n\npolicies = {"A":"Tight: weekly review, safety stock optimization",\n    "B":"Moderate: monthly review, standard ROP","C":"Simple: large orders, periodic review"}\nfor c, p in policies.items():\n    print("  {} policy: {}".format(c, p))\n\nfig, ax1 = plt.subplots(figsize=(12,6))\ncolors = df["abc"].map({"A":"#e63946","B":"#e9c46a","C":"#2a9d8f"}).values\nax1.bar(range(n), df["value"], color=colors, width=1.0)\nax2 = ax1.twinx()\nax2.plot(range(n), df["cum_pct"], color="#a8dadc", linewidth=2)\nax2.axhline(y=80, color="#e63946", linestyle="--", alpha=0.5)\nax2.axhline(y=95, color="#e9c46a", linestyle="--", alpha=0.5)\nax1.set_title("ABC Pareto", color="#f8f9fb")\nax1.set_facecolor("#0b1d2a"); fig.set_facecolor("#091722")\nplt.tight_layout()\nplt.savefig("abc.png", dpi=150, facecolor="#091722")',['~20% SKUs = ~80% value','Pareto chart shows bar + line','Different policies per class','Counts and percentages correct'],'ABC is step one — you cannot manage 10K SKUs the same way.'),
  lg(2,'inventory-mgmt','Inventory Management','Safety Stock Calculation',['Calculate safety stock for service level','Understand stock vs stockout trade-off'],['Collect daily demand history','Calculate demand std deviation','Choose service level (95% = z=1.65)','Calculate: SS = z * sigma * sqrt(lead_time)','Calculate ROP = avg_demand * LT + SS','Analyze cost: extra holding vs stockout'],'SS = z * sigma * sqrt(LT). Higher service = higher z = more stock = higher cost. 95%: z=1.65, 99%: z=2.33.','import numpy as np\nfrom scipy import stats\n\ndemand = np.array([100,95,110,105,98,115,90,108,102,97])\nmu = demand.mean(); sigma = demand.std()\nLT = 7; sl = 0.95\nz = stats.norm.ppf(sl)\nss = z * sigma * np.sqrt(LT)\nrop = mu * LT + ss\nprint("SS: {:.0f} units (z={:.2f})".format(ss, z))\nprint("ROP: {:.0f} units".format(rop))','Safety stock optimizer with sensitivity.','import numpy as np\nfrom scipy import stats\n\nnp.random.seed(42)\ndemand = np.random.normal(100, 15, 90).clip(min=0)\nmu = demand.mean(); sigma = demand.std(); LT = 7\n\nprint("=== Demand Stats ===")\nprint("Mean: {:.1f}, Std: {:.1f}, Lead time: {} days".format(mu, sigma, LT))\n\nprint("\\n=== Safety Stock by Service Level ===")\nfor sl in [0.85, 0.90, 0.95, 0.97, 0.99]:\n    z = stats.norm.ppf(sl)\n    ss = z * sigma * np.sqrt(LT)\n    rop = mu * LT + ss\n    hold = ss * 0.50  # annual holding cost\n    print("  {:.0%}: SS={:.0f}, ROP={:.0f}, Holding={:.0f}/yr".format(sl, ss, rop, hold))\n\n# Optimal balance\nstockout_cost = 50  # per unit\nhold_cost = 0.50    # per unit per year\nz_vals = np.linspace(0, 3, 100)\nss_vals = z_vals * sigma * np.sqrt(LT)\nholding = ss_vals * hold_cost\nstockout_prob = 1 - stats.norm.cdf(z_vals)\nstockout = stockout_prob * (365/LT) * mu * stockout_cost / 100\ntotal = holding + stockout\n\nopt = np.argmin(total)\nprint("\\nOptimal z: {:.2f}, SS: {:.0f}, Service: {:.1%}".format(\n    z_vals[opt], ss_vals[opt], stats.norm.cdf(z_vals[opt])))',['Formula correctly applied','Multiple service levels compared','ROP includes safety stock','Cost trade-off quantified'],'Safety stock is insurance — the question is how much risk you accept.'),
  lg(3,'inventory-mgmt','Inventory Management','Reorder Point Optimization',['Calculate ROP with demand and lead time variability','Simulate inventory behavior'],['Define ROP = avg demand during LT + safety stock','Account for LT variability','Simulate 365 days: demand, replenishment, stockouts','Track fill rate','Adjust ROP until target met','Plot inventory over time'],'When both demand AND lead time vary: sigma = sqrt(LT*sigma_d^2 + d^2*sigma_LT^2).','import numpy as np\nd_avg, d_std = 100, 15\nlt_avg, lt_std = 7, 2\nsigma = np.sqrt(lt_avg*d_std**2 + d_avg**2*lt_std**2)\nz = 1.65\nss = z * sigma\nrop = d_avg * lt_avg + ss\nprint("Combined sigma: {:.1f}".format(sigma))\nprint("Safety stock: {:.0f}".format(ss))\nprint("ROP: {:.0f}".format(rop))','Inventory simulation with dynamic ROP.','import numpy as np\n\nnp.random.seed(42)\nd_avg, d_std = 100, 15\nlt_avg, lt_std = 7, 1.5\norder_qty = 700\nz = 1.65\n\nsigma = np.sqrt(lt_avg*d_std**2 + d_avg**2*lt_std**2)\nss = z * sigma\nrop = d_avg * lt_avg + ss\n\nprint("=== ROP Calculation ===")\nprint("Avg demand: {}/day, LT: {} days".format(d_avg, lt_avg))\nprint("Combined sigma: {:.1f}".format(sigma))\nprint("Safety stock: {:.0f}".format(ss))\nprint("ROP: {:.0f}".format(rop))\n\n# Simulate\ndays = 365\ninv = np.zeros(days)\ninv[0] = order_qty + ss\nstockouts = 0\npending = None\norders = 0\n\nfor day in range(1, days):\n    demand = max(0, np.random.normal(d_avg, d_std))\n    if pending and day >= pending:\n        inv[day] = inv[day-1] + order_qty - demand\n        pending = None\n    else:\n        inv[day] = inv[day-1] - demand\n    if inv[day] < 0:\n        stockouts += 1; inv[day] = 0\n    if inv[day] <= rop and pending is None:\n        lt = max(1, int(np.random.normal(lt_avg, lt_std)))\n        pending = day + lt; orders += 1\n\nfill = 1 - stockouts/days\nprint("\\n=== Simulation ===")\nprint("Fill rate: {:.1%}".format(fill))\nprint("Stockout days: {}".format(stockouts))\nprint("Orders placed: {}".format(orders))\nprint("Avg inventory: {:.0f}".format(inv.mean()))',['ROP includes both variabilities','365-day simulation','Fill rate meets target','Clear reorder cycles shown'],'ROP optimization: where theory meets reality.'),
  lg(4,'inventory-mgmt','Inventory Management','FIFO vs LIFO vs Weighted Average',['Calculate COGS under 3 methods','Understand financial impact'],['Create transaction log: purchases and sales','Calculate COGS using FIFO (oldest first)','Calculate COGS using LIFO (newest first)','Calculate weighted average','Compare ending inventory values','Analyze: which gives lowest taxes in rising prices?'],'FIFO sells oldest first (lower COGS in rising prices). LIFO sells newest (higher COGS, lower taxes). Weighted average is between.','purchases = [(100,10.00),(150,11.00),(120,12.00)]\nsold = 200\nfifo = 100*10.00 + 100*11.00\ntotal_cost = sum(q*c for q,c in purchases)\ntotal_qty = sum(q for q,_ in purchases)\navg = total_cost/total_qty\nprint("FIFO COGS: {:.2f}".format(fifo))\nprint("Wtd Avg COGS: {:.2f}".format(sold*avg))','Complete valuation comparison.','import pandas as pd\n\npurchases = [("2025-01",100,10.00),("2025-02",150,11.00),("2025-03",120,12.00),("2025-04",80,12.50)]\ntotal_qty = sum(q for _,q,_ in purchases)\ntotal_cost = sum(q*c for _,q,c in purchases)\ntotal_sold = 300\n\ndef fifo(purchases, sold):\n    remaining = sold; cogs = 0\n    for _,q,c in purchases:\n        take = min(remaining, q); cogs += take*c; remaining -= take\n        if remaining <= 0: break\n    return cogs\n\ndef lifo(purchases, sold):\n    remaining = sold; cogs = 0\n    for _,q,c in reversed(purchases):\n        take = min(remaining, q); cogs += take*c; remaining -= take\n        if remaining <= 0: break\n    return cogs\n\ndef wavg(purchases, sold):\n    total_c = sum(q*c for _,q,c in purchases)\n    total_q = sum(q for _,q,_ in purchases)\n    return sold * (total_c/total_q)\n\nprint("=== Inventory Valuation ===")\nprint("Purchased: {} units at {:,.2f}".format(total_qty, total_cost))\nprint("Sold: {} units".format(total_sold))\nprint("Remaining: {} units".format(total_qty-total_sold))\n\nfor method, fn in [("FIFO",fifo),("LIFO",lifo),("Wtd Avg",wavg)]:\n    cogs = fn(purchases, total_sold)\n    ending = total_cost - cogs\n    profit = total_sold*15 - cogs  # sell at 15\n    tax = profit * 0.25\n    print("\\n{}:".format(method))\n    print("  COGS: {:,.2f} | Ending: {:,.2f}".format(cogs, ending))\n    print("  Profit: {:,.2f} | Tax: {:,.2f}".format(profit, tax))',['All 3 methods calculated','COGS differs between methods','Ending values reconcile','Tax impact quantified'],'Valuation method directly affects reported profit and taxes.'),
  lg(5,'inventory-mgmt','Inventory Management','Bullwhip Effect Simulation',['Simulate demand amplification','Identify causes and mitigations'],['Create 4-tier chain: retail > distributor > manufacturer > supplier','Generate consumer demand with slight variability','Each tier orders with safety buffer','Track order quantities over 52 weeks','Measure variance amplification','Identify mitigation strategies'],'Bullwhip: 10% demand change at retail becomes 40% at manufacturer. Causes: batching, forecast errors, promotion gaming.','import numpy as np\nnp.random.seed(42)\nweeks = 52\nconsumer = np.random.normal(100, 10, weeks)\nretail = np.zeros(weeks)\nfor w in range(1, weeks):\n    retail[w] = consumer[w] + 0.3*(consumer[w]-consumer[w-1])\nprint("Consumer std: {:.1f}".format(consumer.std()))\nprint("Retail std: {:.1f}".format(retail[1:].std()))\nprint("Amplification: {:.2f}x".format(retail[1:].std()/consumer.std()))','Full bullwhip simulation across 4 tiers.','import numpy as np\nimport matplotlib.pyplot as plt\n\nnp.random.seed(42)\nweeks = 52\nconsumer = np.random.normal(100, 8, weeks).clip(min=50)\n\ndef simulate_tier(downstream, overreact=0.3, buffer=1.1):\n    orders = np.zeros(weeks)\n    orders[0] = downstream[0]*buffer\n    for w in range(1, weeks):\n        trend = downstream[w] - downstream[w-1]\n        orders[w] = max(0, downstream[w]*buffer + overreact*trend)\n    return orders\n\nretailer = simulate_tier(consumer, 0.3, 1.05)\ndistributor = simulate_tier(retailer, 0.4, 1.10)\nmanufacturer = simulate_tier(distributor, 0.5, 1.15)\nsupplier = simulate_tier(manufacturer, 0.5, 1.20)\n\ntiers = {"Consumer":consumer,"Retailer":retailer,"Distributor":distributor,\n    "Manufacturer":manufacturer,"Supplier":supplier}\n\nprint("=== Bullwhip Analysis ===")\nbase = consumer.std()\nfor name, data in tiers.items():\n    amp = data.std()/base\n    print("  {}: mean={:.0f}, std={:.1f}, amp={:.2f}x".format(name, data.mean(), data.std(), amp))\n\nfig, ax = plt.subplots(figsize=(14,6))\ncolors = ["#a8dadc","#2a9d8f","#e9c46a","#e76f51","#e63946"]\nfor (name,data),color in zip(tiers.items(), colors):\n    ax.plot(range(weeks), data, label=name, color=color, alpha=0.8)\nax.set_xlabel("Week"); ax.set_ylabel("Order Qty")\nax.set_title("Bullwhip Effect", color="#f8f9fb")\nax.legend(facecolor="#142a3b",labelcolor="#f8f9fb")\nax.set_facecolor("#0b1d2a"); fig.set_facecolor("#091722")\nplt.tight_layout()\nplt.savefig("bullwhip.png", dpi=150, facecolor="#091722")\n\nprint("\\nMitigations:")\nfor m in ["Share POS data (visibility)","Smaller frequent orders","Stable pricing","VMI"]:\n    print("  - " + m)',['Variance increases upstream','Amplification >2x at manufacturer','Chart shows widening oscillations','3+ mitigations identified'],'A 5% sales dip at retail can cause a 50% production cut at the supplier.'),
  lg(1,'transport-plan','Transportation Planning','Mode Comparison',['Compare modes on cost, speed, capacity','Build selection matrix'],['Define 5 modes: truck, rail, air, ocean, intermodal','Compare: cost/ton-mile, transit time, capacity, reliability','Create comparison matrix','Build decision tool by weight/distance/urgency','Calculate cost for sample shipment','Identify when intermodal wins'],'Air for urgent/light, ocean for heavy/slow, truck for flexible/domestic, rail for bulk/long.','modes = {"Truck":{"cpm":0.12,"days":1.5,"tons":22},\n    "Rail":{"cpm":0.04,"days":4,"tons":100},\n    "Air":{"cpm":0.80,"days":0.3,"tons":5},\n    "Ocean":{"cpm":0.01,"days":15,"tons":25}}\nfor m, s in modes.items():\n    cost = s["cpm"]*15*1000  # 15 tons, 1000 miles\n    print("{}: {} days, {:,.0f}".format(m, s["days"], cost))','Mode selector with cost optimization.','import pandas as pd\n\nmodes = pd.DataFrame([\n    {"mode":"Truck FTL","cpm":0.12,"days_1k":1.5,"max_tons":22,"reliability":0.95,"best":"Domestic door-to-door"},\n    {"mode":"Truck LTL","cpm":0.18,"days_1k":3,"max_tons":10,"reliability":0.90,"best":"Small shipments"},\n    {"mode":"Rail","cpm":0.04,"days_1k":4,"max_tons":100,"reliability":0.85,"best":"Bulk long-distance"},\n    {"mode":"Air","cpm":0.80,"days_1k":0.3,"max_tons":5,"reliability":0.98,"best":"Urgent high-value"},\n    {"mode":"Ocean","cpm":0.01,"days_1k":15,"max_tons":25,"reliability":0.80,"best":"International bulk"},\n    {"mode":"Intermodal","cpm":0.06,"days_1k":5,"max_tons":22,"reliability":0.88,"best":"Long domestic cost-conscious"},\n])\n\ndef recommend(weight, distance, max_days, budget=None):\n    e = modes[modes.max_tons >= weight].copy()\n    e["days"] = e["days_1k"]*distance/1000\n    e["cost"] = e["cpm"]*weight*distance\n    e = e[e["days"] <= max_days]\n    if budget: e = e[e["cost"] <= budget]\n    return e.sort_values("cost")\n\nprint("=== Mode Comparison ===")\nprint(modes[["mode","cpm","days_1k","reliability"]].to_string(index=False))\n\nprint("\\n=== Rec: 15 tons, 2000 mi, max 5 days ===")\nfor _, r in recommend(15, 2000, 5).iterrows():\n    print("  {}: {:,.0f} in {:.1f} days".format(r["mode"], r["cost"], r["days"]))',['5+ modes compared','Cost/speed/capacity quantified','Decision tool works','Intermodal included'],'No universally best mode — it depends on weight, distance, urgency.'),
  lg(2,'transport-plan','Transportation Planning','Route Optimization (Dijkstra)',['Implement shortest path algorithm','Find optimal routes'],['Create city graph with distances','Implement Dijkstra step by step','Find shortest path','Trace path and total distance','Compare with brute force to verify','Visualize with optimal path'],'Dijkstra explores nodes by distance from source, always expanding the closest unvisited. Use heapq for priority queue.','import heapq\n\ngraph = {"A":{"B":4,"C":2},"B":{"D":3},"C":{"B":1,"D":5},"D":{}}\n\ndef dijkstra(g, start):\n    dist = {n:float("inf") for n in g}; dist[start] = 0\n    pq = [(0, start)]\n    while pq:\n        d, u = heapq.heappop(pq)\n        for v, w in g[u].items():\n            if d+w < dist[v]:\n                dist[v] = d+w; heapq.heappush(pq, (dist[v], v))\n    return dist\n\nprint(dijkstra(graph, "A"))','Dijkstra with path reconstruction.','import heapq\n\ndef dijkstra(graph, start, end):\n    dist = {n:float("inf") for n in graph}; dist[start] = 0\n    prev = {n:None for n in graph}\n    pq = [(0, start)]; visited = set()\n    while pq:\n        d, cur = heapq.heappop(pq)\n        if cur in visited: continue\n        visited.add(cur)\n        if cur == end: break\n        for nb, w in graph[cur].items():\n            nd = d + w\n            if nd < dist[nb]:\n                dist[nb] = nd; prev[nb] = cur\n                heapq.heappush(pq, (nd, nb))\n    path = []; node = end\n    while node: path.append(node); node = prev[node]\n    path.reverse()\n    return dist[end], path\n\nnet = {\n    "Chicago":{"Detroit":280,"Indianapolis":180,"Milwaukee":90},\n    "Detroit":{"Chicago":280,"Cleveland":170,"Indianapolis":290},\n    "Indianapolis":{"Chicago":180,"Detroit":290,"Cincinnati":110,"Louisville":115},\n    "Cleveland":{"Detroit":170,"Pittsburgh":130,"Cincinnati":250},\n    "Cincinnati":{"Indianapolis":110,"Cleveland":250,"Louisville":100,"Pittsburgh":290},\n    "Louisville":{"Indianapolis":115,"Cincinnati":100,"Nashville":175},\n    "Nashville":{"Louisville":175,"Atlanta":250},\n    "Pittsburgh":{"Cleveland":130,"Cincinnati":290,"Philadelphia":305},\n    "Philadelphia":{"Pittsburgh":305,"New York":95},\n    "Milwaukee":{"Chicago":90},"Atlanta":{"Nashville":250},"New York":{"Philadelphia":95},\n}\n\nfor dest in ["New York","Atlanta","Cincinnati"]:\n    d, p = dijkstra(net, "Chicago", dest)\n    print("Chicago -> {}: {} mi via {}".format(dest, d, " > ".join(p)))',['Finds globally shortest path','Path reconstruction works','10+ cities handled','Verifiable results'],'Dijkstra is the foundation of every GPS and routing system.'),
  lg(3,'transport-plan','Transportation Planning','Vehicle Routing Problem',['Solve capacitated VRP with OR-Tools','Minimize distance with capacity constraints'],['Install: pip install ortools','Define: depot, customers, demands, capacity','Create distance matrix','Set up OR-Tools routing model','Solve and extract routes','Calculate utilization per vehicle'],'VRP extends TSP with multiple vehicles and capacity. OR-Tools handles optimization — you define the problem.','from ortools.constraint_solver import routing_enums_pb2, pywrapcp\nmanager = pywrapcp.RoutingIndexManager(5, 1, 0)\nrouting = pywrapcp.RoutingModel(manager)\nprint("OR-Tools VRP initialized: 5 locations, 1 vehicle")','Complete VRP solver.','from ortools.constraint_solver import routing_enums_pb2, pywrapcp\nimport numpy as np\n\nnp.random.seed(42)\nlocs = [(0,0)] + [(np.random.randint(-50,50), np.random.randint(-50,50)) for _ in range(9)]\nn = len(locs)\ndm = [[0]*n for _ in range(n)]\nfor i in range(n):\n    for j in range(n):\n        dm[i][j] = int(np.sqrt((locs[i][0]-locs[j][0])**2 + (locs[i][1]-locs[j][1])**2))\n\ndemands = [0, 10, 15, 20, 10, 25, 15, 10, 20, 15]\ncaps = [50, 50, 50]\n\nmgr = pywrapcp.RoutingIndexManager(n, len(caps), 0)\nrouting = pywrapcp.RoutingModel(mgr)\n\ndef dist_cb(fi, ti):\n    return dm[mgr.IndexToNode(fi)][mgr.IndexToNode(ti)]\ntidx = routing.RegisterTransitCallback(dist_cb)\nrouting.SetArcCostEvaluatorOfAllVehicles(tidx)\n\ndef dem_cb(idx): return demands[mgr.IndexToNode(idx)]\ndidx = routing.RegisterUnaryTransitCallback(dem_cb)\nrouting.AddDimensionWithVehicleCapacity(didx, 0, caps, True, "Cap")\n\nparams = pywrapcp.DefaultRoutingSearchParameters()\nparams.first_solution_strategy = routing_enums_pb2.FirstSolutionStrategy.PATH_CHEAPEST_ARC\nsol = routing.SolveWithParameters(params)\n\nif sol:\n    print("=== VRP Solution ===")\n    total = 0\n    for v in range(len(caps)):\n        route = []; load = 0; idx = routing.Start(v)\n        while not routing.IsEnd(idx):\n            node = mgr.IndexToNode(idx); route.append(str(node)); load += demands[node]\n            idx = sol.Value(routing.NextVar(idx))\n        route.append("0")\n        rdist = sum(dm[int(route[i])][int(route[i+1])] for i in range(len(route)-1))\n        total += rdist\n        print("  V{}: {} (load:{}/{}, dist:{})".format(v, "->".join(route), load, caps[v], rdist))\n    print("Total distance: {}".format(total))',['VRP solved with capacity','Multiple routes from depot','Distance minimized','Utilization reported'],'VRP: OR-Tools makes hard optimization accessible.'),
  lg(4,'transport-plan','Transportation Planning','Freight Cost Analysis',['Analyze costs by lane','Find consolidation opportunities'],['Load shipment data: origin, dest, weight, cost','Calculate cost/mile and cost/lb by lane','Identify top 10 expensive lanes','Find consolidation: multiple small on same lane','Calculate LTL->FTL savings','Recommend carrier allocation'],'Lane analysis reveals overpaying. Consolidating 3 LTL into 1 FTL saves 30-40%.','import pandas as pd, numpy as np\nnp.random.seed(42)\ndf = pd.DataFrame({"lane":np.random.choice(["CHI-NYC","LA-SF","DAL-ATL"],100),\n    "weight":np.random.randint(500,20000,100),\n    "cost":np.random.uniform(200,5000,100),\n    "miles":np.random.randint(200,2500,100)})\ndf["cpm"] = df["cost"]/df["miles"]\nprint(df.groupby("lane")["cpm"].agg(["mean","count"]).round(2))','Complete lane analysis with consolidation.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\nn = 500\nlanes = ["Chicago>NYC","LA>SF","Dallas>Atlanta","Chicago>LA","NYC>Miami","Seattle>Portland"]\ndf = pd.DataFrame({"id":range(n),"lane":np.random.choice(lanes,n),\n    "carrier":np.random.choice(["Fast","Value","Express","Budget"],n),\n    "weight":np.random.randint(200,25000,n),\n    "cost":np.random.uniform(150,6000,n).round(2),\n    "miles":np.random.randint(150,2800,n),\n    "type":np.random.choice(["LTL","FTL"],n,p=[0.6,0.4])})\ndf["cpm"] = (df["cost"]/df["miles"]).round(3)\n\nprint("=== Lane Analysis ===")\nstats = df.groupby("lane").agg(shipments=("id","count"),avg_cost=("cost","mean"),\n    avg_cpm=("cpm","mean"),total=("cost","sum"),\n    ltl_pct=("type",lambda x:(x=="LTL").mean())).round(2).sort_values("total",ascending=False)\nprint(stats.to_string())\n\nprint("\\n=== Consolidation ===")\nfor lane in lanes:\n    ltl = df[(df.lane==lane)&(df.type=="LTL")]\n    if len(ltl) > 5:\n        savings = ltl["cost"].sum() * 0.30\n        print("  {}: {} LTL shipments, est savings: {:,.0f}".format(lane, len(ltl), savings))\n\nprint("\\n=== Carrier Performance ===")\nprint(df.groupby("carrier").agg(avg_cpm=("cpm","mean"),count=("id","count")).round(3).sort_values("avg_cpm").to_string())',['Lane-level costs analyzed','Expensive lanes identified','Consolidation savings estimated','Carrier performance compared'],'Most companies overpay 15-25% because they do not analyze at lane level.'),
  lg(5,'transport-plan','Transportation Planning','Fleet Utilization Dashboard',['Track fleet metrics','Identify idle capacity'],['Define: utilization, empty miles %, idle time','Calculate utilization = loaded/total miles','Track vehicle status','Find least utilized','Calculate cost per mile and per delivery','Recommend fleet right-sizing'],'Utilization = loaded/total miles. Below 70% = too many empty backhauls. Above 85% = little buffer.','import pandas as pd, numpy as np\nnp.random.seed(42)\nfleet = pd.DataFrame({"vehicle":["V-{:03d}".format(i) for i in range(10)],\n    "loaded":np.random.randint(5000,15000,10),\n    "empty":np.random.randint(1000,5000,10)})\nfleet["total"] = fleet["loaded"]+fleet["empty"]\nfleet["util"] = (fleet["loaded"]/fleet["total"]*100).round(1)\nprint(fleet[["vehicle","util"]].sort_values("util").to_string(index=False))','Complete fleet dashboard.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\nn = 20\nfleet = pd.DataFrame({"id":["V-{:03d}".format(i+1) for i in range(n)],\n    "type":np.random.choice(["Box","Semi","Van","Flat"],n),\n    "loaded":np.random.randint(3000,18000,n),\n    "empty":np.random.randint(500,6000,n),\n    "fuel_gal":np.random.randint(300,2500,n),\n    "maint":np.random.uniform(200,3000,n).round(2),\n    "idle_hrs":np.random.randint(10,300,n),\n    "total_hrs":np.random.randint(300,600,n),\n    "deliveries":np.random.randint(20,200,n)})\n\nfleet["total_mi"] = fleet["loaded"]+fleet["empty"]\nfleet["util"] = (fleet["loaded"]/fleet["total_mi"]*100).round(1)\nfleet["empty_pct"] = (fleet["empty"]/fleet["total_mi"]*100).round(1)\nfleet["cost_mi"] = ((fleet["maint"]+fleet["fuel_gal"]*4)/fleet["total_mi"]).round(3)\nfleet["cost_del"] = ((fleet["maint"]+fleet["fuel_gal"]*4)/fleet["deliveries"]).round(2)\n\nprint("=== Fleet Dashboard ===")\nprint("Fleet: {} vehicles".format(n))\nprint("Avg util: {:.1f}%".format(fleet["util"].mean()))\nprint("Avg empty: {:.1f}%".format(fleet["empty_pct"].mean()))\nprint("Avg cost/mi: {:.3f}".format(fleet["cost_mi"].mean()))\n\nprint("\\n=== Top 5 ===")\nprint(fleet.nlargest(5,"util")[["id","type","util","cost_mi"]].to_string(index=False))\n\nprint("\\n=== Bottom 5 (Consider Retiring) ===")\nprint(fleet.nsmallest(5,"util")[["id","type","util","cost_mi"]].to_string(index=False))\n\nunder = fleet[fleet["util"]<60]\nif len(under):\n    savings = under["maint"].sum()+under["fuel_gal"].sum()*4\n    print("\\n{} vehicles under 60% -> retire for {:,.0f}/yr savings".format(len(under), savings))',['Utilization calculated correctly','Empty miles tracked','Cost per delivery computed','Under-utilized flagged'],'Utilization data tells you which vehicles earn their keep.'),
  lg(1,'warehouse-ops','Warehouse Operations','Warehouse Layout Design',['Design zones for optimal flow','Calculate space per zone'],['Define zones: receiving, storage, picking, packing, shipping','Estimate throughput per zone','Calculate space = throughput x dwell x sqft/pallet','Arrange for minimal pick-to-pack travel','Apply U-flow or through-flow','Document dimensions'],'U-flow: receiving and shipping same wall (small WH). Through-flow: opposite walls (high volume).','zones = {"Receiving":{"pallets":100,"dwell_hrs":2,"sqft":20},\n    "Storage":{"pallets":100,"dwell_hrs":168,"sqft":15},\n    "Picking":{"pallets":80,"dwell_hrs":1,"sqft":25},\n    "Packing":{"pallets":80,"dwell_hrs":0.5,"sqft":30},\n    "Shipping":{"pallets":80,"dwell_hrs":3,"sqft":20}}\nfor z, s in zones.items():\n    cap = s["pallets"]*s["dwell_hrs"]/24\n    sqft = cap*s["sqft"]\n    print("{}: {:.0f} pallets, {:,.0f} sqft".format(z, cap, sqft))','Complete layout calculator.','import pandas as pd\n\nzones = pd.DataFrame([\n    {"zone":"Receiving","pallets_day":120,"dwell_hrs":2,"sqft_per":20,"staff":4},\n    {"zone":"Bulk Storage","pallets_day":120,"dwell_hrs":336,"sqft_per":12,"staff":2},\n    {"zone":"Pick Storage","pallets_day":100,"dwell_hrs":48,"sqft_per":18,"staff":8},\n    {"zone":"Packing","pallets_day":100,"dwell_hrs":1,"sqft_per":30,"staff":6},\n    {"zone":"Shipping","pallets_day":100,"dwell_hrs":3,"sqft_per":20,"staff":4},\n    {"zone":"Returns","pallets_day":15,"dwell_hrs":24,"sqft_per":25,"staff":2},\n])\nzones["avg_pallets"] = (zones["pallets_day"]*zones["dwell_hrs"]/24).round(0)\nzones["sqft"] = (zones["avg_pallets"]*zones["sqft_per"]).round(0)\n\nprint("=== Space Requirements ===")\nprint(zones[["zone","avg_pallets","sqft","staff"]].to_string(index=False))\nprint("\\nTotal: {:,.0f} sqft, {} staff".format(zones["sqft"].sum(), zones["staff"].sum()))\n\nprint("\\n=== Adjacency ===")\nfor z1,z2,reason in [("Receiving","Bulk Storage","shared dock"),\n    ("Pick Storage","Packing","minimize travel"),("Packing","Shipping","adjacent flow")]:\n    print("  {} <-> {}: {}".format(z1, z2, reason))',['Space per zone calculated','Adjacency defined','Total footprint computed','Staff per zone documented'],'Good layout minimizes travel — fastest pick needs no walking.'),
  lg(2,'warehouse-ops','Warehouse Operations','Slotting Optimization',['Assign by velocity','Maximize pick efficiency'],['Classify by frequency: A/B/C movers','Assign: A=golden zone, C=bulk','Calculate current travel distance','Re-slot by velocity','Measure improvement','Create slotting map'],'Golden zone = waist height, near shipping. Top 20% movers go there.','import pandas as pd, numpy as np\nnp.random.seed(42)\ndf = pd.DataFrame({"sku":["P{:03d}".format(i) for i in range(50)],\n    "picks_wk":np.random.lognormal(3,1.5,50).astype(int)})\ndf = df.sort_values("picks_wk",ascending=False).reset_index(drop=True)\ndf["zone"] = ["Golden"]*10+["Standard"]*20+["Bulk"]*20\ndf["dist"] = [10]*10+[40]*20+[80]*20\ntravel = (df["picks_wk"]*df["dist"]).sum()\nprint("Weekly travel: {:,} ft".format(travel))','Complete slotting optimizer.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\nn = 100\ndf = pd.DataFrame({"sku":["SKU-{:04d}".format(i) for i in range(n)],\n    "picks_wk":np.random.lognormal(3,1.5,n).astype(int)+1,\n    "weight":np.random.uniform(0.5,50,n).round(1)})\n\nnp.random.shuffle(df.index.values)\ndf["current_dist"] = np.random.randint(10,150,n)\n\ndf = df.sort_values("picks_wk",ascending=False).reset_index(drop=True)\ndf["velocity"] = pd.cut(df.index, bins=[-1,20,50,100], labels=["A-Fast","B-Med","C-Slow"])\nzone_dist = {"A-Fast":15,"B-Med":50,"C-Slow":100}\ndf["optimal_dist"] = df["velocity"].map(zone_dist)\n\ndf["current_travel"] = df["picks_wk"]*df["current_dist"]\ndf["optimal_travel"] = df["picks_wk"]*df["optimal_dist"]\n\ncur = df["current_travel"].sum()\nopt = df["optimal_travel"].sum()\nsave = (1-opt/cur)*100\n\nprint("=== Slotting Results ===")\nprint("Current: {:>12,} ft/wk".format(cur))\nprint("Optimal: {:>12,} ft/wk".format(opt))\nprint("Savings: {:>12,} ft/wk ({:.0f}%)".format(cur-opt, save))\n\nfor z in ["A-Fast","B-Med","C-Slow"]:\n    sub = df[df.velocity==z]\n    print("  {}: {} SKUs, {:,} picks/wk, {}ft avg".format(z, len(sub), sub["picks_wk"].sum(), zone_dist[z]))',['Products classified by velocity','Fast movers closest','Travel reduction quantified','20%+ savings achieved'],'Slotting is highest-ROI warehouse optimization.'),
  lg(3,'warehouse-ops','Warehouse Operations','Pick Path Optimization',['Compare picking strategies','Minimize travel distance'],['Generate pick list with aisle/bay locations','Implement S-shape traversal','Implement nearest-neighbor','Calculate distance for each','Compare by pick list size','Recommend based on layout'],'S-shape: simple, good for dense picks. Nearest-neighbor: better for sparse picks.','import numpy as np\nnp.random.seed(42)\npicks = [(np.random.randint(1,10),np.random.randint(1,20)) for _ in range(15)]\nsorted_picks = sorted(picks, key=lambda p: (p[0], p[1] if p[0]%2==0 else -p[1]))\ntotal = sum(abs(a[0]-b[0])*10+abs(a[1]-b[1])*3 for a,b in zip(sorted_picks,sorted_picks[1:]))\nprint("S-shape: {} ft ({} picks)".format(total, len(picks)))','Pick path comparison.','import numpy as np\n\nnp.random.seed(42)\n\ndef dist(a, b, aw=10, bd=3):\n    return abs(a[0]-b[0])*aw + abs(a[1]-b[1])*bd\n\ndef s_shape(picks, start=(0,0)):\n    sp = sorted(picks, key=lambda p: (p[0], p[1] if p[0]%2==0 else -p[1]))\n    route = [start]+sp+[start]\n    return sum(dist(route[i],route[i+1]) for i in range(len(route)-1))\n\ndef nearest_nb(picks, start=(0,0)):\n    route = [start]; remaining = list(picks)\n    while remaining:\n        cur = route[-1]\n        nearest = min(remaining, key=lambda p: dist(cur,p))\n        route.append(nearest); remaining.remove(nearest)\n    route.append(start)\n    return sum(dist(route[i],route[i+1]) for i in range(len(route)-1))\n\nprint("=== Pick Path Comparison ===")\nfor n_picks in [5, 10, 15, 20, 30]:\n    picks = [(np.random.randint(1,10), np.random.randint(1,25)) for _ in range(n_picks)]\n    sd = s_shape(picks)\n    nd = nearest_nb(picks)\n    winner = "S-shape" if sd < nd else "Nearest"\n    save = abs(sd-nd)/max(sd,nd)*100\n    print("  {:2d} picks: S={:4d}ft, NN={:4d}ft -> {} ({:.0f}% better)".format(n_picks,sd,nd,winner,save))\n\nprint("\\nDense picks: S-shape. Sparse: Nearest-neighbor.")',['2+ strategies compared','Distance calculated each','Winner identified by scenario','Recommendation provided'],'Saving 2-5s per pick x 500 picks/day = 30+ minutes saved daily.'),
  lg(4,'warehouse-ops','Warehouse Operations','Warehouse KPIs',['Track core operational metrics','Build KPI dashboard'],['Define 8 KPIs: picks/hr, accuracy, dock-to-stock, space utilization, cycle time, inv accuracy, labor cost/unit, on-time ship','Collect week of data','Calculate each KPI','Set targets and RAG thresholds','Create dashboard with trends','Identify biggest opportunity'],'Picks/hour is #1 metric. World-class: 150-200 for case picking. Below 80: layout/process issues.','kpis = {"Picks/Hr":{"actual":120,"target":150},\n    "Accuracy":{"actual":99.2,"target":99.5},\n    "Dock-to-Stock":{"actual":4.5,"target":2.0},\n    "Space Util":{"actual":78,"target":85}}\nfor name, k in kpis.items():\n    ok = k["actual"]>=k["target"] if name!="Dock-to-Stock" else k["actual"]<=k["target"]\n    print("{} {}: {} (target {})".format("OK" if ok else "!!", name, k["actual"], k["target"]))','Complete warehouse KPI tracker.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\ndays = pd.date_range("2025-03-01",periods=28)\ndata = pd.DataFrame({"date":days,\n    "picks":np.random.randint(3000,5000,28),\n    "labor_hrs":np.random.uniform(30,45,28).round(1),\n    "orders":np.random.randint(200,400,28),\n    "accurate":np.random.randint(195,400,28),\n    "dts_hrs":np.random.uniform(1.5,6,28).round(1),\n    "used_locs":np.random.randint(700,950,28)})\ndata["accurate"] = data[["accurate","orders"]].min(axis=1)\ndata["pph"] = (data["picks"]/data["labor_hrs"]).round(1)\ndata["acc_pct"] = (data["accurate"]/data["orders"]*100).round(2)\ndata["space"] = (data["used_locs"]/1000*100).round(1)\ndata["week"] = data["date"].dt.isocalendar().week\n\nweekly = data.groupby("week").agg(\n    pph=("pph","mean"),acc=("acc_pct","mean"),\n    dts=("dts_hrs","mean"),space=("space","mean")).round(1)\n\nprint("=== Warehouse KPIs ===")\ntargets = {"pph":130,"acc":99.5,"dts":3.0,"space":85}\nfor col, target in targets.items():\n    latest = weekly[col].iloc[-1]\n    higher = col != "dts"\n    ok = (latest>=target) if higher else (latest<=target)\n    print("{} {}: {} (target: {})".format("OK" if ok else "!!", col, latest, target))\n\nprint("\\n=== Weekly Trends ===")\nprint(weekly.to_string())',['8+ KPIs calculated','Each vs target','Trends identified','Biggest opportunity highlighted'],'You cannot improve what you do not measure.'),
  lg(5,'warehouse-ops','Warehouse Operations','Automation ROI Analysis',['Calculate payback and NPV','Compare manual vs automated'],['List options: conveyors, AS/RS, pick-to-light, AMR','Estimate current manual cost','Get automation costs','Calculate savings: labor + error + throughput','Payback = investment / annual savings','5-year NPV with discount rate'],'2-3 year payback is good. Beyond 5 years is risky.','invest = 500000\nlabor_save = 180000\nerror_save = 30000\nthroughput_save = 20000\ntotal = labor_save + error_save + throughput_save\npayback = invest / total\nprint("Annual savings: {:,}".format(total))\nprint("Payback: {:.1f} years".format(payback))','Complete automation ROI comparison.','import numpy as np\n\ndef roi(name, invest, annual_save, annual_op, years=5, rate=0.08):\n    net = annual_save - annual_op\n    payback = invest/net if net>0 else float("inf")\n    cfs = [-invest]+[net]*years\n    npv = sum(cf/(1+rate)**t for t, cf in enumerate(cfs))\n    return {"name":name,"invest":invest,"net":net,"payback":payback,"npv":npv}\n\noptions = [\n    roi("Conveyors",200000,120000,15000),\n    roi("Pick-to-Light",150000,90000,10000),\n    roi("AS/RS",1200000,350000,50000),\n    roi("AMR Fleet",500000,200000,40000),\n    roi("Voice Pick",80000,60000,12000),\n]\n\nprint("=== Automation ROI ===")\nfor o in sorted(options, key=lambda x:x["npv"], reverse=True):\n    ok = "OK" if o["payback"]<3 else ("??" if o["payback"]<5 else "NO")\n    print("[{}] {}".format(ok, o["name"]))\n    print("    Invest: {:>10,}  Net/yr: {:>10,}".format(o["invest"],o["net"]))\n    print("    Payback: {:.1f}yr  NPV(5yr): {:>10,.0f}".format(o["payback"],o["npv"]))\n\nbest = max(options, key=lambda x:x["npv"])\nprint("\\nRecommendation: {} (NPV: {:,.0f})".format(best["name"], best["npv"]))',['4+ options compared','Payback calculated','NPV with discount rate','Clear recommendation'],'Automation decisions should be driven by NPV, not excitement.'),
  lg(1,'demand-forecast','Demand Forecasting','Time Series Decomposition',['Decompose into trend, seasonality, residual','Identify additive vs multiplicative'],['Load 2+ years of demand data','Plot raw series','Apply seasonal_decompose (additive and multiplicative)','Compare: which fits better?','Extract and interpret components','Check residuals are random'],'Additive: constant seasonal amplitude. Multiplicative: amplitude grows with trend.','import pandas as pd, numpy as np\nfrom statsmodels.tsa.seasonal import seasonal_decompose\n\nnp.random.seed(42)\ndates = pd.date_range("2023-01-01",periods=730,freq="D")\ntrend = np.linspace(100,150,730)\nseason = 20*np.sin(np.arange(730)*2*np.pi/365)\ndemand = pd.Series(trend+season+np.random.normal(0,5,730), index=dates)\nresult = seasonal_decompose(demand, period=365, model="additive")\nprint("Trend: {:.0f} to {:.0f}".format(result.trend.min(), result.trend.max()))\nprint("Seasonal amplitude: {:.1f}".format(result.seasonal.max()))','Full decomposition analysis.','import pandas as pd, numpy as np\nfrom statsmodels.tsa.seasonal import seasonal_decompose\n\nnp.random.seed(42)\nmonths = pd.date_range("2022-01-01",periods=36,freq="M")\ntrend = np.linspace(1000,1500,36)\nseasonal = 200*np.sin(np.arange(36)*2*np.pi/12)\ndemand = pd.Series((trend+seasonal+np.random.normal(0,50,36)).clip(min=0), index=months)\n\nresult_add = seasonal_decompose(demand, period=12, model="additive")\nresult_mul = seasonal_decompose(demand, period=12, model="multiplicative")\n\nprint("=== Decomposition ===")\nprint("Mean: {:.0f}/month".format(demand.mean()))\nprint("Trend: {:.0f} -> {:.0f}".format(result_add.trend.dropna().iloc[0], result_add.trend.dropna().iloc[-1]))\nprint("Seasonal range: {:.0f} to {:.0f}".format(result_add.seasonal.min(), result_add.seasonal.max()))\nprint("Residual std: {:.1f}".format(result_add.resid.std()))\n\nadd_std = result_add.resid.dropna().std()\nmul_std = result_mul.resid.dropna().std()\nbetter = "Additive" if add_std < mul_std*demand.mean() else "Multiplicative"\nprint("\\nBetter model: {} (add resid std: {:.1f})".format(better, add_std))',['Decomposed into 3 components','Additive vs multiplicative compared','Trend and seasonality identified','Residuals checked'],'Decomposition is step one — if you see the pattern, you can predict it.'),
  lg(2,'demand-forecast','Demand Forecasting','Moving Averages and Smoothing',['Apply SMA, EMA, Holt-Winters','Tune parameters'],['Calculate SMA with windows 7,14,30','Calculate EMA with alpha 0.1,0.3,0.5','Apply Holt-Winters','Compare on holdout data','Tune for best fit','Recommend best method'],'SMA lags. EMA reacts faster. Holt-Winters handles trend + seasonality.','import pandas as pd, numpy as np\nnp.random.seed(42)\ndemand = pd.Series(np.random.normal(100,10,60))\nsma7 = demand.rolling(7).mean()\nema = demand.ewm(alpha=0.3).mean()\nprint("Latest: {:.0f}".format(demand.iloc[-1]))\nprint("SMA(7): {:.0f}".format(sma7.iloc[-1]))\nprint("EMA(0.3): {:.0f}".format(ema.iloc[-1]))','Smoothing comparison with tuning.','import pandas as pd, numpy as np\nfrom statsmodels.tsa.holtwinters import ExponentialSmoothing\nimport warnings; warnings.filterwarnings("ignore")\n\nnp.random.seed(42)\nmonths = pd.date_range("2023-01-01",periods=24,freq="M")\ntrend = np.linspace(800,1200,24)\nseason = 150*np.sin(np.arange(24)*2*np.pi/12)\ndemand = pd.Series(trend+season+np.random.normal(0,40,24), index=months)\ntrain, test = demand[:18], demand[18:]\n\nresults = {}\nfor w in [3,6]:\n    f = train.rolling(w).mean().iloc[-1]\n    preds = pd.Series([f]*len(test), index=test.index)\n    results["SMA({})".format(w)] = (test-preds).abs().mean()\n\nfor a in [0.2,0.4]:\n    f = train.ewm(alpha=a).mean().iloc[-1]\n    preds = pd.Series([f]*len(test), index=test.index)\n    results["EMA({})".format(a)] = (test-preds).abs().mean()\n\ntry:\n    hw = ExponentialSmoothing(train,trend="add",seasonal="add",seasonal_periods=12).fit()\n    results["Holt-Winters"] = (test-hw.forecast(len(test))).abs().mean()\nexcept: pass\n\nprint("=== Method Comparison ===")\nfor name, mae in sorted(results.items(), key=lambda x:x[1]):\n    print("  {}: MAE={:.1f}".format(name, mae))\nbest = min(results, key=results.get)\nprint("\\nBest: {} (MAE: {:.1f})".format(best, results[best]))',['SMA, EMA, HW all applied','Multiple parameters tested','Compared on holdout','Best identified'],'Holt-Winters usually wins for demand with trend + seasonality.'),
  lg(3,'demand-forecast','Demand Forecasting','ARIMA Modeling',['Build ARIMA from scratch','Select optimal (p,d,q)'],['Test stationarity with ADF','If non-stationary, difference (d=1)','Plot ACF/PACF for p and q','Fit ARIMA','Forecast next 6 periods','Check residuals are white noise'],'Recipe: 1) Difference until ADF p<0.05. 2) Read p from PACF. 3) Read q from ACF. 4) Fit and check.','import pandas as pd, numpy as np\nfrom statsmodels.tsa.stattools import adfuller\n\nnp.random.seed(42)\ndemand = pd.Series(np.cumsum(np.random.normal(2,5,60))+500)\nresult = adfuller(demand)\nprint("ADF: {:.4f}, p-value: {:.4f}".format(result[0], result[1]))\nprint("Stationary: {}".format("Yes" if result[1]<0.05 else "No"))','Complete ARIMA pipeline.','import pandas as pd, numpy as np\nfrom statsmodels.tsa.stattools import adfuller\nfrom statsmodels.tsa.arima.model import ARIMA\nimport warnings; warnings.filterwarnings("ignore")\n\nnp.random.seed(42)\nmonths = pd.date_range("2022-01-01",periods=36,freq="M")\ndemand = pd.Series(np.cumsum(np.random.normal(15,10,36))+1000+np.random.normal(0,30,36), index=months)\n\nadf = adfuller(demand)\nprint("ADF: {:.4f}, p={:.4f}, Stationary: {}".format(adf[0],adf[1],"Yes" if adf[1]<0.05 else "No"))\n\nd = 0\nif adf[1] >= 0.05:\n    d = 1\n    adf2 = adfuller(demand.diff().dropna())\n    print("After diff: p={:.4f}".format(adf2[1]))\n\ntrain, test = demand[:30], demand[30:]\nbest_aic, best_order = float("inf"), None\nfor p in range(3):\n    for q in range(3):\n        try:\n            m = ARIMA(train, order=(p,d,q)).fit()\n            if m.aic < best_aic: best_aic = m.aic; best_order = (p,d,q)\n        except: pass\n\nprint("Best: {} (AIC: {:.1f})".format(best_order, best_aic))\n\nmodel = ARIMA(train, order=best_order).fit()\nfc = model.forecast(len(test))\nmae = (test-fc).abs().mean()\nprint("\\nForecast MAE: {:.1f}".format(mae))\nfor d2, a, f in zip(test.index, test.values, fc.values):\n    print("  {}: actual={:.0f}, forecast={:.0f}".format(d2.strftime("%Y-%m"), a, f))\n\nresid = model.resid\nprint("\\nResidual mean: {:.2f}, autocorr: {:.3f}".format(resid.mean(), resid.autocorr()))',['ADF test used','Multiple orders compared by AIC','Forecast on holdout','Residuals checked'],'ARIMA: robust, interpretable, surprisingly hard to beat.'),
  lg(4,'demand-forecast','Demand Forecasting','Forecast Accuracy Metrics',['Calculate MAE, RMSE, MAPE, bias','Build accuracy tracking'],['Generate forecasts from 3 methods','Calculate MAE','Calculate RMSE','Calculate MAPE','Calculate bias','Rank methods and select best'],'MAE: intuitive. MAPE: scale-independent. RMSE: penalizes big misses. Bias: systematic drift.','import numpy as np\nactual = np.array([100,110,95,120,105])\nforecast = np.array([98,115,90,118,108])\nerr = actual-forecast\nprint("MAE: {:.1f}".format(np.abs(err).mean()))\nprint("RMSE: {:.1f}".format(np.sqrt((err**2).mean())))\nprint("MAPE: {:.1f}%".format((np.abs(err)/actual).mean()*100))\nprint("Bias: {:.1f}".format(err.mean()))','Forecast accuracy comparison.','import pandas as pd, numpy as np\n\nnp.random.seed(42)\nactual = np.random.normal(1000,100,12).round(0)\nforecasts = {\n    "Naive": actual+np.random.normal(50,80,12),\n    "ARIMA": actual+np.random.normal(-5,60,12),\n    "HW": actual+np.random.normal(0,45,12),\n}\n\ndef evaluate(actual, pred, name):\n    err = actual-pred\n    return {"Method":name,"MAE":round(np.abs(err).mean(),1),\n        "RMSE":round(np.sqrt((err**2).mean()),1),\n        "MAPE":round((np.abs(err)/actual).mean()*100,1),\n        "Bias":round(err.mean(),1)}\n\nresults = [evaluate(actual, pred, name) for name, pred in forecasts.items()]\ndf = pd.DataFrame(results).sort_values("MAE")\nprint("=== Accuracy Comparison ===")\nprint(df.to_string(index=False))\n\nbest = df.iloc[0]\nprint("\\nBest: {} (MAE: {:.0f}, Bias: {:.0f})".format(best["Method"], best["MAE"], best["Bias"]))\n\nfor name, pred in forecasts.items():\n    errs = actual-pred\n    ts = errs.cumsum()[-1]/np.abs(errs).mean()\n    ok = "OK" if abs(ts)<4 else "OUT OF CONTROL"\n    print("  {} tracking signal: {:.2f} [{}]".format(name, ts, ok))',['All 4 metrics calculated','3+ methods compared','Bias direction identified','Tracking signal computed'],'Accuracy is about knowing how wrong you are and in which direction.'),
  lg(5,'demand-forecast','Demand Forecasting','Ensemble Forecasting',['Combine forecasts into weighted ensemble','Weight by historical accuracy'],['Generate forecasts from 3 methods','Calculate accuracy weights: inverse MAE','Create weighted average ensemble','Compare ensemble vs individuals','Test: does ensemble always win?','Document when ensembles add value'],'Weighted: weight_i = (1/MAE_i) / sum(1/MAE_j). Ensemble often beats best individual because errors cancel.','import numpy as np\nactual = np.array([100,110,95,120,105])\nf1 = np.array([98,112,92,118,110])\nf2 = np.array([102,108,97,125,100])\nmae1 = np.abs(actual-f1).mean()\nmae2 = np.abs(actual-f2).mean()\nw1 = (1/mae1)/(1/mae1+1/mae2); w2 = 1-w1\nens = w1*f1 + w2*f2\nprint("F1: {:.1f}, F2: {:.1f}, Ensemble: {:.1f}".format(mae1,mae2,np.abs(actual-ens).mean()))','Full ensemble system.','import pandas as pd, numpy as np\nfrom statsmodels.tsa.holtwinters import ExponentialSmoothing\nfrom statsmodels.tsa.arima.model import ARIMA\nimport warnings; warnings.filterwarnings("ignore")\n\nnp.random.seed(42)\nmonths = pd.date_range("2022-01-01",periods=36,freq="M")\ntrend = np.linspace(800,1200,36)\nseasonal = 100*np.sin(np.arange(36)*2*np.pi/12)\ndemand = pd.Series(trend+seasonal+np.random.normal(0,40,36), index=months)\ntrain, test = demand[:30], demand[30:]\n\ndef sma_fc(tr, h): return pd.Series([tr.iloc[-6:].mean()]*h, index=test.index)\ndef arima_fc(tr, h): return ARIMA(tr,order=(1,1,1)).fit().forecast(h)\ndef hw_fc(tr, h): return ExponentialSmoothing(tr,trend="add",seasonal="add",seasonal_periods=12).fit().forecast(h)\n\nfcs = {"SMA":sma_fc(train,len(test)),"ARIMA":arima_fc(train,len(test)),"HW":hw_fc(train,len(test))}\n\n# Weights from validation\nweights = {}\nfor name, fn in [("SMA",sma_fc),("ARIMA",arima_fc),("HW",hw_fc)]:\n    try:\n        val_pred = fn(demand[:24], 6)\n        mae = (demand[24:30]-val_pred).abs().mean()\n        weights[name] = 1/max(mae,1)\n    except: weights[name] = 0.1\ntw = sum(weights.values())\nweights = {k:v/tw for k,v in weights.items()}\n\nensemble = sum(fcs[n]*w for n,w in weights.items())\n\nprint("=== Ensemble Comparison ===")\nall_fcs = {**fcs, "Ensemble":ensemble}\nfor name, pred in all_fcs.items():\n    mae = (test-pred).abs().mean()\n    w = weights.get(name, "-")\n    ws = "{:.2f}".format(w) if isinstance(w,float) else w\n    print("  {:10s}: MAE={:.1f}, Weight={}".format(name, mae, ws))\n\nens_mae = (test-ensemble).abs().mean()\nbest_ind = min(((n,(test-p).abs().mean()) for n,p in fcs.items()), key=lambda x:x[1])\nprint("\\nEnsemble {} by {:.1f}".format("wins" if ens_mae<best_ind[1] else "loses", abs(ens_mae-best_ind[1])))',['3+ methods combined','Weights from accuracy','Ensemble vs individuals','Error reduction shown'],'Ensemble is the secret weapon — combining diverse methods almost always wins.'),
  lg(1,'last-mile','Last-Mile Delivery','Last-Mile Economics',['Break down delivery cost','Model failed delivery impact'],['Identify costs: driver, vehicle, fuel, loading, failed delivery','Calculate cost per delivery','Model failed delivery: reattempt + contact + holding','Calculate break-even deliveries per route','Compare urban vs suburban','Identify top 3 cost drivers'],'Last mile = 40-53% of total shipping cost. Biggest driver is density — more deliveries per route = lower cost.','driver = 22*8; vehicle = 80; fuel = 45\ndeliveries = 120\nroute_cost = driver+vehicle+fuel\ncost_per = route_cost/deliveries + 0.50\nprint("Route: {:,.0f}".format(route_cost))\nprint("Per delivery: {:.2f}".format(cost_per))','Complete last-mile cost model.','def cost_model(deliveries, fail_rate=0.10):\n    driver = 22*8; vehicle = 80; fuel = 45; loading = 0.50*deliveries\n    route = driver+vehicle+fuel+loading\n    successful = deliveries*(1-fail_rate)\n    failed = deliveries*fail_rate\n    reattempt = failed*8.50; contact = failed*2.00; holding = failed*1.50\n    total = route+reattempt+contact+holding\n    return total/max(successful,1), total, reattempt+contact+holding\n\nprint("=== Cost by Route Density ===")\nfor d in [40,60,80,100,120,150]:\n    cpd, total, fail_cost = cost_model(d)\n    print("  {} deliveries: {:.2f}/del, fail cost: {:.0f}".format(d, cpd, fail_cost))\n\nprint("\\n=== Impact of Failure Rate ===")\nfor r in [0.05,0.10,0.15,0.20]:\n    cpd, _, fc = cost_model(100, r)\n    print("  {:.0%}: {:.2f}/del (reattempt: {:.0f})".format(r, cpd, fc))\n\nprint("\\nReducing failures from 15% to 5% saves more than adding 20 stops.")',['All cost components included','Failed delivery impact quantified','Density effect shown','Scenarios compared'],'Reducing failed deliveries is almost always more profitable than optimizing routes.'),
  lg(2,'last-mile','Last-Mile Delivery','Delivery Zone Design',['Cluster addresses into balanced zones','Optimize for equal workload'],['Geocode addresses','Apply k-means clustering','Calculate workload per zone','Rebalance until equal','Visualize zones','Assign drivers by capacity'],'K-means on lat/lng gives geographic clusters. Rebalance for equal workload.','import numpy as np\nfrom sklearn.cluster import KMeans\nnp.random.seed(42)\nlats = np.random.normal(40.7,0.05,200)\nlngs = np.random.normal(-74.0,0.05,200)\ncoords = np.column_stack([lats,lngs])\nkm = KMeans(n_clusters=5, random_state=42).fit(coords)\nfor z in range(5):\n    print("Zone {}: {} deliveries".format(z, (km.labels_==z).sum()))','Complete zone designer.','import numpy as np\nfrom sklearn.cluster import KMeans\nimport matplotlib.pyplot as plt\n\nnp.random.seed(42)\ndowntown = np.random.normal([40.72,-73.99],[0.01,0.01],(150,2))\nuptown = np.random.normal([40.78,-73.96],[0.02,0.02],(80,2))\nsuburban = np.random.normal([40.70,-73.94],[0.03,0.03],(70,2))\ncoords = np.vstack([downtown,uptown,suburban])\n\nprint("=== Zone Optimization ===")\nfor n in range(3,9):\n    km = KMeans(n_clusters=n,random_state=42,n_init=10).fit(coords)\n    sizes = [np.sum(km.labels_==i) for i in range(n)]\n    imb = max(sizes)/min(sizes)\n    print("  {} zones: sizes={}, imbalance={:.2f}x".format(n, sizes, imb))\n\nn_z = 6\nkm = KMeans(n_clusters=n_z,random_state=42,n_init=10).fit(coords)\nsizes = [np.sum(km.labels_==i) for i in range(n_z)]\nimb = max(sizes)/min(sizes)\n\nprint("\\n=== Selected: {} zones ===")\nfor i in range(n_z):\n    zc = coords[km.labels_==i]\n    r = np.mean(np.sqrt(np.sum((zc-km.cluster_centers_[i])**2,axis=1)))*111\n    print("  Zone {}: {} deliveries, radius: {:.2f}km".format(i, sizes[i], r))\nprint("Balance: {:.2f}x".format(imb))\n\ncolors = ["#e63946","#2a9d8f","#e9c46a","#457b9d","#a8dadc","#e76f51"]\nfig, ax = plt.subplots(figsize=(10,8))\nfor i in range(n_z):\n    mask = km.labels_==i\n    ax.scatter(coords[mask,1],coords[mask,0],c=colors[i],s=20,alpha=0.6,label="Zone {} ({})".format(i,sizes[i]))\n    ax.scatter(km.cluster_centers_[i,1],km.cluster_centers_[i,0],c=colors[i],s=200,marker="*",edgecolors="white")\nax.legend(facecolor="#142a3b",labelcolor="#f8f9fb")\nax.set_facecolor("#0b1d2a"); fig.set_facecolor("#091722")\nplt.tight_layout()\nplt.savefig("zones.png",dpi=150,facecolor="#091722")',['Geographic clusters coherent','Workload balanced (<2x ratio)','Multiple zone counts tested','Zones visualized'],'Imbalanced zones mean one driver finishes at 2PM while another is out until 8PM.'),
  lg(3,'last-mile','Last-Mile Delivery','Dynamic Routing',['Simulate real-time adjustments','Balance speed vs optimality'],['Create depot + initial route','New orders arrive every 30 min','Nearest-insertion for real-time','Compare with periodic re-optimization','Track distance and lateness','Find sweet spot for re-opt frequency'],'Nearest insertion is fast but suboptimal. Full re-opt is better but slow. Practical: insert real-time, re-opt every N orders.','import numpy as np\nnp.random.seed(42)\nstops = [(np.random.uniform(0,100),np.random.uniform(0,100)) for _ in range(10)]\nnew = (50,50)\nbest_pos, best_inc = 0, float("inf")\nfor i in range(len(stops)-1):\n    d = np.hypot(stops[i][0]-new[0],stops[i][1]-new[1]) + \\\n        np.hypot(new[0]-stops[i+1][0],new[1]-stops[i+1][1]) - \\\n        np.hypot(stops[i][0]-stops[i+1][0],stops[i][1]-stops[i+1][1])\n    if d < best_inc: best_inc = d; best_pos = i+1\nprint("Insert at {}, cost: {:.1f}".format(best_pos, best_inc))','Dynamic dispatch simulator.','import numpy as np\n\nnp.random.seed(42)\n\ndef route_dist(r):\n    return sum(np.hypot(r[i][0]-r[i+1][0],r[i][1]-r[i+1][1]) for i in range(len(r)-1))\n\ndef insert(route, stop):\n    best_pos, best_cost = 1, float("inf")\n    for i in range(1, len(route)):\n        cost = np.hypot(route[i-1][0]-stop[0],route[i-1][1]-stop[1]) + \\\n               np.hypot(stop[0]-route[i][0],stop[1]-route[i][1]) - \\\n               np.hypot(route[i-1][0]-route[i][0],route[i-1][1]-route[i][1])\n        if cost < best_cost: best_cost = cost; best_pos = i\n    route.insert(best_pos, stop)\n    return route\n\ndef nn_route(stops, depot):\n    route = [depot]; remaining = list(stops)\n    while remaining:\n        cur = route[-1]\n        nearest = min(remaining, key=lambda s: np.hypot(cur[0]-s[0],cur[1]-s[1]))\n        route.append(nearest); remaining.remove(nearest)\n    route.append(depot)\n    return route\n\ndepot = (50,50)\ninitial = [(np.random.uniform(10,90),np.random.uniform(10,90)) for _ in range(15)]\nnew_orders = [(np.random.uniform(10,90),np.random.uniform(10,90)) for _ in range(10)]\n\n# Strategy 1: Insert only\nr1 = nn_route(initial[:], depot)\nfor o in new_orders: r1 = insert(r1, o)\n\n# Strategy 2: Re-opt every 5\nr2 = nn_route(initial[:], depot)\nall_stops = list(initial)\nfor i, o in enumerate(new_orders):\n    all_stops.append(o)\n    if (i+1)%5==0: r2 = nn_route(all_stops[:], depot)\n    else: r2 = insert(r2, o)\n\nprint("=== Dynamic Routing ===")\nprint("Initial: {}, New: {}".format(len(initial), len(new_orders)))\nprint("Insert-only: {:.0f}".format(route_dist(r1)))\nprint("Re-opt (every 5): {:.0f}".format(route_dist(r2)))\nsave = (route_dist(r1)-route_dist(r2))/route_dist(r1)*100\nprint("Savings: {:.1f}%".format(save))',['Dynamic insertion simulated','Two strategies compared','Re-opt frequency tested','Speed vs optimality quantified'],'Good-enough decisions fast beat perfect routes that arrive late.'),
  lg(4,'last-mile','Last-Mile Delivery','Customer Experience Metrics',['Track delivery satisfaction','Identify satisfaction drivers'],['Define: on-time rate, first-attempt, window accuracy, CSAT','Collect delivery data with timestamps','Calculate each metric','Segment by zone/driver/time','Correlate window width with satisfaction','Identify top 3 levers'],'Narrower windows increase satisfaction but cost more. Sweet spot: 2-hour window with real-time tracking.','import pandas as pd, numpy as np\nnp.random.seed(42)\nn = 500\ndf = pd.DataFrame({"on_time":np.random.choice([True,False],n,p=[0.88,0.12]),\n    "first_attempt":np.random.choice([True,False],n,p=[0.92,0.08]),\n    "csat":np.random.choice([1,2,3,4,5],n,p=[0.02,0.05,0.13,0.35,0.45])})\nprint("On-time: {:.1%}".format(df.on_time.mean()))\nprint("First attempt: {:.1%}".format(df.first_attempt.mean()))\nprint("CSAT: {:.2f}/5".format(df.csat.mean()))','Complete CX metrics dashboard.','import pandas as pd, numpy as np\n\nnp.random.seed(42)\nn = 1000\ndf = pd.DataFrame({"id":range(n),\n    "zone":np.random.choice(["Downtown","Midtown","Uptown","Suburban"],n),\n    "time_slot":np.random.choice(["9-11","11-1","1-3","3-5","5-7"],n),\n    "on_time":np.random.choice([True,False],n,p=[0.88,0.12]),\n    "first_attempt":np.random.choice([True,False],n,p=[0.90,0.10]),\n    "csat":np.random.choice([1,2,3,4,5],n,p=[0.02,0.05,0.13,0.35,0.45])})\n\nprint("=== CX Dashboard ===")\nprint("On-time: {:.1%}".format(df.on_time.mean()))\nprint("First attempt: {:.1%}".format(df.first_attempt.mean()))\nprint("CSAT: {:.2f}/5".format(df.csat.mean()))\n\nprint("\\n=== By Zone ===")\nzs = df.groupby("zone").agg(on_time=("on_time","mean"),first=("first_attempt","mean"),\n    csat=("csat","mean"),count=("id","count")).round(3)\nprint(zs.to_string())\n\nprint("\\n=== By Time Slot ===")\nts = df.groupby("time_slot").agg(on_time=("on_time","mean"),csat=("csat","mean")).round(3)\nprint(ts.sort_values("on_time").to_string())\n\nworst_zone = zs["on_time"].idxmin()\nworst_slot = ts["on_time"].idxmin()\nprint("\\n=== Improvement Levers ===")\nprint("1. Fix {} zone ({:.1%})".format(worst_zone, zs.loc[worst_zone,"on_time"]))\nprint("2. Fix {} slot ({:.1%})".format(worst_slot, ts.loc[worst_slot,"on_time"]))\nprint("3. Reduce failed first attempts ({:.1%})".format(1-df.first_attempt.mean()))',['On-time, first-attempt, CSAT calculated','Segmented by zone and time','Worst segments identified','Specific recommendations'],'Show up when promised, and do not make customers wait all day.'),
  lg(5,'last-mile','Last-Mile Delivery','Sustainability Metrics',['Calculate CO2 per delivery','Model EV fleet transition'],['Calculate emissions for current diesel fleet','Compare: diesel van, EV, cargo bike','Cost per kg CO2 avoided','Build 5-year transition timeline','Estimate total reduction and cost','Create sustainability dashboard'],'Diesel: ~0.3 kg CO2/km. EV: ~0.05 kg/km. Cargo bike: 0. Shorter routes = less emissions.','diesel = 0.27  # kg CO2/km\nkm_per = 2.5\ndeliveries = 120\ndaily = diesel*km_per*deliveries\nprint("Daily CO2: {:.0f} kg".format(daily))\nprint("Annual: {:.1f} tonnes".format(daily*260/1000))\nprint("Per delivery: {:.2f} kg".format(daily/deliveries))','Fleet sustainability analysis.','import numpy as np\n\ndef fleet_emissions(mix, km_per_day=150, days=260):\n    factors = {"diesel":0.27,"electric":0.05,"cargo_bike":0.0}\n    costs_daily = {"diesel":45,"electric":12,"cargo_bike":0}\n    costs_annual_maint = {"diesel":3000,"electric":1500,"cargo_bike":500}\n    purchase = {"diesel":35000,"electric":55000,"cargo_bike":5000}\n    life = {"diesel":8,"electric":10,"cargo_bike":5}\n    \n    total_co2 = 0; total_cost = 0\n    for vtype, count in mix.items():\n        annual_km = km_per_day*days*count\n        co2 = annual_km*factors[vtype]\n        cost = (costs_daily[vtype]*days + costs_annual_maint[vtype] + purchase[vtype]/life[vtype])*count\n        total_co2 += co2; total_cost += cost\n    return total_co2/1000, total_cost\n\nprint("=== Current (All Diesel) ===")\nco2_base, cost_base = fleet_emissions({"diesel":20})\nprint("  CO2: {:.0f} tonnes, Cost: {:,.0f}/yr".format(co2_base, cost_base))\n\ntransitions = [\n    (1, {"diesel":16,"electric":4}),\n    (2, {"diesel":12,"electric":8}),\n    (3, {"diesel":8,"electric":10,"cargo_bike":2}),\n    (4, {"diesel":4,"electric":12,"cargo_bike":4}),\n    (5, {"diesel":0,"electric":14,"cargo_bike":6}),\n]\n\nprint("\\n=== 5-Year Transition ===")\nfor yr, mix in transitions:\n    co2, cost = fleet_emissions(mix)\n    red = (1-co2/co2_base)*100\n    delta = cost-cost_base\n    sign = "+" if delta>=0 else ""\n    print("Year {}: {:.0f}t CO2 ({:.0f}% reduction), cost delta: {}{:,.0f}".format(yr, co2, red, sign, delta))\n    for v, n in mix.items():\n        if n>0: print("    {}: {}".format(v, n))\n\nprint("\\nYear 5: 90%+ CO2 reduction, approaching cost parity")',['CO2 per delivery calculated','EV vs diesel compared','Multi-year plan with targets','Cost per tonne CO2 quantified'],'Green logistics is also good business — EVs have lower operating costs within 3-4 years.'),
];
